// A monochrome paperclip decorates external destinations without replacing descriptive text.
(()=>{function decorate(){for(const link of document.querySelectorAll('a[href^="https://"],a[href^="http://"]')){if(link.origin===location.origin||link.dataset.externalIcon)continue;link.dataset.externalIcon='true';for(const node of link.childNodes)if(node.nodeType===3)node.textContent=node.textContent.replace(/↗/g,'').trimEnd();const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');icon.setAttribute('viewBox','0 0 24 24');icon.setAttribute('class','external-paperclip');icon.setAttribute('aria-hidden','true');icon.innerHTML='<path d="m8 13 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7L12 3a6 6 0 0 1 8 8l-8 8" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>';link.append(icon);const accessible=document.createElement('span');accessible.className='visually-hidden';accessible.textContent=' (external link)';link.append(accessible);if(link.hasAttribute('aria-label'))link.setAttribute('aria-label',link.getAttribute('aria-label')+' (external link)');}}
 let pending=false;new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;decorate();});}}).observe(document.body,{childList:true,subtree:true});decorate();})();
